raw_response:
{
  "objective": "Recover the checkout for basket basket_266 after a 3DS failure, ensuring payment safety.",
  "desired_outcome": "OUTCOME_OK",
  "params": {
    "basket_id": "literal 'basket_266'",
    "payment": "lookup from payment_transactions WHERE basket_id = $basket_id",
    "max_attempts": "lookup from $payment.three_ds_max_attempts",
    "current_attempts": "lookup from $payment.three_ds_attempts"
  },
  "outcome_space": [
    "OUTCOME_OK",
    "OUTCOME_DENIED_SECURITY",
    "OUTCOME_NONE_UNSUPPORTED"
  ],
  "constraints": [
    {
      "anchor": "# Customer Ownership",
      "rule": "Customers can only access their own records.",
      "security": true,
      "deny_when": {
        "op": "or",
        "args": [
          {"op": "ne", "lhs": "$_facts.identity.kind", "rhs": "customer"},
          {"op": "ne", "lhs": "$basket.customer_id", "rhs": "$_facts.identity.customer_id"}
        ]
      }
    },
    {
      "anchor": "# 3DS Retry Limit",
      "rule": "3DS retry is allowed only if the number of attempts is less than the maximum allowed.",
      "security": false,
      "deny_when": {
        "op": "ge",
        "lhs": "$payment.three_ds_attempts",
        "rhs": "$payment.three_ds_max_attempts"
      }
    }
  ],
  "success_criteria": {
    "OUTCOME_OK": [
      {"op": "eq", "lhs": "$payment.three_ds_status", "rhs": "successful"},
      {"op": "eq", "lhs": "$payment.payment_status", "rhs": "completed"}
    ]
  },
  "answer_shape": {
    "msg_skeleton": "Checkout recovered for basket {basket_id}. Payment {payment.payment_id} processed with successful 3DS."
  },
  "required_refs": {
    "OUTCOME_OK": [
      {"kind": "policy_doc", "path": "/docs/payments/3ds.md"},
      {"kind": "record_path", "source": "$payment.record_path"}
    ]
  }
}

